class XorLoader extends ClassLoader {
    private final String name; private final byte[] encryptedBytes; private final byte xorKey;
    XorLoader(String name, byte[] encryptedBytes, byte xorKey) { this.name = name; this.encryptedBytes = encryptedBytes; this.xorKey = xorKey; }
    protected Class<?> findClass(String n) throws ClassNotFoundException {
        byte[] decrypted = new byte[encryptedBytes.length];
        for (int i = 0; i < encryptedBytes.length; i++) decrypted[i] = (byte) (encryptedBytes[i] ^ xorKey);
        return defineClass(n, decrypted, 0, decrypted.length);
    }
}

