// W JVM nie istnieje mechanizm 'wyladuj TE JEDNA klase' na zadanie - klasy sa TRWALE
// zwiazane z class loaderem, ktory je zaladowal, przez cala swoja 'zywotnosc'. Metadane
// klasy (bajtkod metod, constant pool, informacje o polach) sa przechowywane w METASPACE -
// obszarze pamieci poza zwyklym heapem, dedykowanym wlasnie metadanym klas.
// Garbage Collector moze odzyskac przestrzen metaspace zajeta przez klase TYLKO wtedy,
// gdy CALY graf obiektow zwiazanych z jej class loaderem (sam loader, wszystkie zaladowane
// przez niego klasy, WSZYSTKIE instancje tych klas) staje sie nieosiagalny z korzeni GC.
// Dlatego 'unload' klasy jest w praktyce SKUTKIEM UBOCZNYM zebrania przez GC calego
// class loadera, a nie osobna, celowa operacja - dlatego systemy pluginow musza dbac,
// by po 'wylaczeniu' pluginu ZADNA referencja do jego loadera/klas/instancji nie przetrwala.

class PluginFramework {
    record Entry(ClassLoader loader, Object instance) {}
    Map<String, Entry> registry = new HashMap<>();

    void register(String name, byte[] classBytes) throws Exception {
        ClassLoader loader = new SimpleLoader(name, classBytes);
        Object instance = loader.loadClass(name).getDeclaredConstructor().newInstance();
        registry.put(name, new Entry(loader, instance)); // NADPISANIE - stara Entry traci referencje
    }

    void describeAll() throws Exception {
        for (var e : registry.entrySet()) {
            Method describe = e.getValue().instance().getClass().getMethod("describe");
            System.out.println(e.getKey() + ": " + describe.invoke(e.getValue().instance()));
        }
    }
}

PluginFramework framework = new PluginFramework();
framework.register("MyPlugin", bytesV1);
framework.describeAll(); // "wersja 1"
framework.register("MyPlugin", bytesV2); // przeladowanie
framework.describeAll(); // "wersja 2"
